// Verify shared webhook secret sent by the Medusa subscriber.
// The secret is passed in the x-webhook-secret header.
const secret = $env.N8N_WEBHOOK_SECRET ?? '';
const received = $input.first().headers?.['x-webhook-secret'] ?? '';

if (secret && received !== secret) {
  throw new Error('Invalid webhook secret — request rejected');
}

// Extract customer fields from the order payload.
const order = $input.first().json;
const customer = order.customer ?? {};
const email = (customer.email ?? '').toLowerCase().trim();
const firstName = typeof customer.first_name === 'string' ? customer.first_name : email.split('@')[0];
const lastName = typeof customer.last_name === 'string' ? customer.last_name : '';

if (!email) {
  throw new Error('Order payload missing customer.email — cannot enroll');
}

// Extract thinkific_course_id from each line item's product metadata.
// Only keep items that actually have a course ID.
const courseItems = (order.items ?? []).reduce((acc, item) => {
  const meta = item?.variant?.product?.metadata;
  const courseId = meta?.thinkific_course_id;
  if (courseId != null && String(courseId).trim() !== '') {
    const title = item?.variant?.product?.title ?? item?.title ?? 'Course';
    acc.push({
      thinkific_course_id: Number(courseId),
      title,
    });
  }
  return acc;
}, []);

return [{
  json: {
    orderId: order.id,
    email,
    firstName,
    lastName,
    courseItems,
    hasCourseItems: courseItems.length > 0,
    thinkificBaseUrl: 'https://api.thinkific.com/api/public/v1',
    thinkificApiKey: $env.THINKIFIC_API_KEY ?? '',
  }
}];

// User found — extract the ID from the first result.
const prep = $('Parse: Order + Extract Course IDs').first().json;
const findResult = $input.first().json;
const user = (findResult.items ?? [])[0];
if (!user || !user.id) throw new Error('Thinkific: user lookup returned empty items unexpectedly');

return [{
  json: {
    ...prep,
    thinkificUserId: user.id,
    thinkificUserFound: true,
  }
}];

// Capture the new user ID from the create response.
const prep = $('Parse: Order + Extract Course IDs').first().json;
const createResult = $input.first().json;
if (!createResult.id) throw new Error('Thinkific: user creation did not return an id: ' + JSON.stringify(createResult).slice(0, 200));

return [{
  json: {
    ...prep,
    thinkificUserId: createResult.id,
    thinkificUserFound: false,
  }
}];

// Merge both branches — user was either found or just created.
// At this point $input.first() carries the fully populated context from
// whichever branch ran. Both branches include thinkificUserId.
const ctx = $input.first().json;
if (!ctx.thinkificUserId) throw new Error('thinkificUserId not resolved — should not reach here');

// Build one enrollment task per course item.
// We tag each with activated_at = now ISO.
const activatedAt = new Date().toISOString();
const enrollmentTasks = ctx.courseItems.map(item => ({
  course_id: item.thinkific_course_id,
  user_id: ctx.thinkificUserId,
  activated_at: activatedAt,
  title: item.title,
}));

return [{
  json: {
    ...ctx,
    enrollmentTasks,
    enrollmentResults: [],
    enrollmentErrors: [],
  }
}];

// Enroll the user in each course, collecting successes and failures.
// Per-enrollment errors are isolated — one failure does not abort the rest.
const ctx = $input.first().json;
const tasks = ctx.enrollmentTasks ?? [];

const successTitles = [];
const errors = [];

for (const task of tasks) {
  try {
    const res = await fetch(ctx.thinkificBaseUrl + '/enrollments', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + ctx.thinkificApiKey,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        course_id: task.course_id,
        user_id: task.user_id,
        activated_at: task.activated_at,
      }),
    });

    if (res.ok) {
      successTitles.push(task.title);
      console.log('[thinkific-enroll] enrolled userId=' + task.user_id + ' courseId=' + task.course_id + ' title=' + task.title);
    } else {
      const body = await res.text();
      const msg = 'Thinkific enrollment HTTP ' + res.status + ' for courseId=' + task.course_id + ': ' + body.slice(0, 300);
      errors.push({ course_id: task.course_id, title: task.title, error: msg });
      console.error('[thinkific-enroll] ' + msg);
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    errors.push({ course_id: task.course_id, title: task.title, error: msg });
    console.error('[thinkific-enroll] fetch error courseId=' + task.course_id + ': ' + msg);
  }
}

return [{
  json: {
    ...ctx,
    enrollmentSuccessTitles: successTitles,
    enrollmentErrors: errors,
    hasErrors: errors.length > 0,
    hasSuccesses: successTitles.length > 0,
  }
}];

// Build and send the customer confirmation email via Resend.
const ctx = $input.first().json;
const courses = ctx.enrollmentSuccessTitles ?? [];
const courseListHtml = courses.map(t => '<li>' + t + '</li>').join('');
const subject = 'Your course access is ready \u2014 ' + courses.join(', ');

const html = [
  '<h2>Welcome to the Ravenall Institute!</h2>',
  '<p>Hi ' + ctx.firstName + ',</p>',
  '<p>Your payment was received and your course access has been activated. You can now start learning:</p>',
  '<ul>' + courseListHtml + '</ul>',
  '<p><a href="https://ravenallinstitute-9629.thinkific.com/collections">Access your courses on Thinkific</a></p>',
  '<p>You will also receive a separate welcome email from Thinkific for the first course — this may land in your promotions or spam folder, so please check there if you do not see it.</p>',
  '<p>If you have any questions, reply to this email and we will help you.</p>',
  '<p>Warm regards,<br>Dr. Suzanne Ravenall</p>',
].join('');

const resendPayload = JSON.stringify({
  from: 'noreply@suzanneravenall.com',
  to: [ctx.email],
  subject,
  html,
});

return [{
  json: {
    ...ctx,
    resendPayload,
    emailSubject: subject,
  }
}];

// Build admin error alert for failed enrollments.
const enrollCtx = $('Enroll: Per Course (isolated failures)').first().json;
const errors = enrollCtx.enrollmentErrors ?? [];
const errorDetails = errors.map(e => `<li>Course ID ${e.course_id} (${e.title}): ${e.error}</li>`).join('');

const subject = '[ALERT] Thinkific enrollment partial failure — order ' + (enrollCtx.orderId ?? 'unknown');
const html = [
  '<h3>Thinkific enrollment errors for order ' + (enrollCtx.orderId ?? 'unknown') + '</h3>',
  '<p>Customer: ' + enrollCtx.email + '</p>',
  '<p>Thinkific user ID: ' + enrollCtx.thinkificUserId + '</p>',
  '<p>Failed enrollments:</p>',
  '<ul>' + errorDetails + '</ul>',
  '<p>Successful: ' + (enrollCtx.enrollmentSuccessTitles ?? []).join(', ') + '</p>',
  '<p>Please manually enroll the customer for the failed course(s) in the Thinkific admin: https://ravenallinstitute-9629.thinkific.com</p>',
  '<p>Time: ' + new Date().toISOString() + '</p>',
].join('');

const sentryDsn = $env.SENTRY_DSN ?? $env.SENTRY_DSN_WEB ?? $env.SENTRY_DSN_MEDUSA ?? '';

return [{
  json: {
    ...enrollCtx,
    adminAlertSubject: subject,
    adminAlertHtml: html,
    sentryDsn,
    hasSentryDsn: !!sentryDsn && !sentryDsn.includes('<DSN'),
  }
}];

// Workflow complete — log outcome.
const ctx = $('Enroll: Per Course (isolated failures)').first().json;
const successes = (ctx.enrollmentSuccessTitles ?? []).length;
const errors = (ctx.enrollmentErrors ?? []).length;
console.log('[thinkific-enroll] DONE orderId=' + (ctx.orderId ?? 'unknown') + ' email=' + ctx.email + ' enrolled=' + successes + ' failed=' + errors);
return [$input.first()];

// Error handler for Thinkific API failures (user lookup or create).
// Called via onError from Thinkific: Find User or Thinkific: Create User.
const errItem = $input.first();
const errorMessage = errItem.error?.message ?? errItem.json?.message ?? 'Unknown error';
let orderId = 'unknown';
let email = 'unknown';
try { orderId = $('Parse: Order + Extract Course IDs').first().json.orderId ?? 'unknown'; } catch {}
try { email = $('Parse: Order + Extract Course IDs').first().json.email ?? 'unknown'; } catch {}

console.error('[thinkific-enroll] FATAL error orderId=' + orderId + ' email=' + email + ' error=' + errorMessage);

const subject = '[ALERT] Thinkific enrollment failed — order ' + orderId;
const html = [
  '<h3>Thinkific enrollment failed for order ' + orderId + '</h3>',
  '<p>Customer: ' + email + '</p>',
  '<p>Error: ' + errorMessage + '</p>',
  '<p>This is a Thinkific API failure (user lookup or creation). Please manually enroll the customer at: https://ravenallinstitute-9629.thinkific.com</p>',
  '<p>Time: ' + new Date().toISOString() + '</p>',
].join('');

return [{
  json: {
    orderId,
    email,
    errorMessage,
    adminAlertSubject: subject,
    adminAlertHtml: html,
  }
}];
